<?php
if(!isset($required_role)){ http_response_code(403); exit('Access denied'); }
session_start(); require_once __DIR__.'/HealthSystem.php';
if(!isset($_SESSION['ID']) || $_SESSION['ROLE'] != $required_role){header('Location: ../login.php');exit;}
$obj=new HealthSystem($pdo); $role=$_SESSION['ROLE']; $title='Patient Records';
if($role=='resident'){ $patient=$obj->show_resident_profile($_SESSION['ID']); }
else{ $patients=$obj->show_residents(); $patient=isset($_GET['id'])?$obj->show_updated_resident((int)$_GET['id']):false; }
require __DIR__.'/module_header.php';
?>
<?php if($role!='resident'): ?><form class="mb-4" method="get"><label>Select patient</label><select name="id" class="form-select mb-2" required><option value="">Select resident</option><?php foreach($patients as $r): ?><option value="<?= e($r['resident_id']) ?>" <?= $patient && $patient['resident_id']==$r['resident_id']?'selected':'' ?>><?= e($r['first_name'].' '.$r['last_name']) ?></option><?php endforeach; ?></select><button class="btn btn-primary">View record</button></form><?php endif; ?>
<?php if($patient): $id=$patient['resident_id']; ?><div class="card p-3 mb-3"><h2 class="h5"><?= e($patient['first_name'].' '.$patient['last_name']) ?></h2><?php foreach(['birth_date','sex','address','contact','health_condition','allergies','emergency_contact','emergency_phone'] as $key): ?><div><strong><?= e(ucwords(str_replace('_',' ',$key))) ?>:</strong> <?= e($patient[$key]) ?></div><?php endforeach; ?></div>
<?php if($role=='bhw'): ?><p><a class="btn btn-primary" href="consultations.php">Record consultation</a> <a class="btn btn-primary" href="vaccinations.php">Record vaccination</a> <a class="btn btn-primary" href="maternal_child.php">Maternal and child records</a></p><?php endif; ?>
<?php $q=$pdo->prepare('SELECT m.medicine_name, t.quantity,t.transaction_date,t.remarks FROM medicine_transactions t JOIN medicines m ON t.medicine_id=m.medicine_id WHERE t.resident_id=? AND t.transaction_type=\'stock_out\' ORDER BY t.transaction_date DESC');$q->execute([$id]); $groups=[['Consultations',$obj->show_resident_consultations($id),['consultation_date','symptoms','assessment','treatment']],['Vaccinations',$obj->show_resident_vaccinations($id),['vaccine_name','dose_number','vaccination_date','next_schedule','status']],['Medicines and supplies received',$q->fetchAll(),['medicine_name','quantity','transaction_date','remarks']]]; foreach($groups as $g): ?><div class="card p-3 mb-3 table-responsive"><h2 class="h5"><?= e($g[0]) ?></h2><table class="table"><tr><?php foreach($g[2] as $key): ?><th><?= e(ucwords(str_replace('_',' ',$key))) ?></th><?php endforeach; ?></tr><?php foreach($g[1] as $r): ?><tr><?php foreach($g[2] as $key): ?><td><?= e($r[$key]) ?></td><?php endforeach; ?></tr><?php endforeach; ?></table><?php if(!$g[1]): ?>No records yet.<?php endif; ?></div><?php endforeach; ?>
<?php else: ?><p>No patient selected or profile not available.</p><?php endif; require __DIR__.'/module_footer.php'; ?>
